18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
41	
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	const BASE_PREMIUM_BY_ITEM_TYPE = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	} as const satisfies Record<string, number>;
53	
54	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
55	
56	const COMPONENT_BLOCK_SIZE = 3;
57	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
58	
59	const sumBasePremiums = (items: Item[]): number => {
60	  if (items.length === COMPONENT_BLOCK_SIZE) return COMPONENT_BLOCK_BASE_PREMIUM;
61	  return items.reduce(
62	    (sum, item) => sum + BASE_PREMIUM_BY_ITEM_TYPE[item.type as InsurableItemType],
63	    0,
64	  );
65	};
66	
67	const quotePremium = (items: Item[]): number => {
68	  const policyBase = sumBasePremiums(items);
69	  const premiumBeforeFee =
70	    policyBase + percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
71	  return Math.ceil(premiumBeforeFee + PROCESSING_FEE);
72	};
73	
74	const runStep = (step: Step): StepResult => {
75	  if (step.op === "quote") return { premium: quotePremium(step.items) };
76	  throw new Error("claim steps are not implemented yet");
77	};
78	
79	export const runScenario = (scenario: Scenario): ScenarioResult => ({
80	  results: scenario.steps.map(runStep),
81	});
